inputs = ['cezifz', 'fvvf', 'vcwy', 'kfkik', 'kkzdzu']
outputs = ['whezifz', 'fegff', 'vwhwy', 'kfkik', 'kkzdzu']

def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out"""
    # Find first position where strings differ
    min_len = min(len(s_in), len(s_out))

    # Look for insertion/deletion or substitution
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're dealing with insertion/deletion
            if len(s_in) < len(s_out):
                # Insertion case: s_out has one more character
                if s_in == s_out[:i] + s_out[i+1:]:
                    return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion case: s_in has one more character  
                if s_out == s_in[:i] + s_in[i+1:]:
                    return (s_in[i], '', i)
            else:
                # Substitution case
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) < len(s_out):
        return (s_in[-1] if s_in else '', s_out[len(s_in)], len(s_in)-1)
    elif len(s_in) > len(s_out):
        return (s_in[len(s_out)], '', len(s_out))
    else:
        return ('', '', -1)  # No difference found

print("Analyzing changes:")
for i, inp, outp in [(0, 'cezifz', 'whezifz'), (1, 'fvvf', 'fegff'), (2, 'vcwy', 'vwhwy')]:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"  {inp} -> {outp}: replace '{old_sub}' with '{new_sub}' at position {pos}")

